### Configure three.js import map in HTML

Source: https://github.com/mrdoob/three.js/blob/dev/manual/pages/installation.html

Defines the mapping for 'three' and 'three/addons/' to a CDN. Replace <version> with a specific version like 'v0.149.0'.

```html
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@<version>/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@<version>/examples/jsm/"
  }
}
</script>
```

--------------------------------

### HalftonePass Usage Example

Source: https://github.com/mrdoob/three.js/blob/dev/docs/pages/HalftonePass.html.md

Demonstrates how to import, instantiate, and add the HalftonePass to a three.js EffectComposer.

```APIDOC
## HalftonePass Initialization and Usage

### Description
This example illustrates the basic steps to integrate the HalftonePass into a three.js post-processing pipeline. It shows how to define parameters, create an instance of HalftonePass, and add it to an EffectComposer.

### Example
```javascript
import { HalftonePass } from 'three/addons/postprocessing/HalftonePass.js';

const params = {
	shape: 1,
	radius: 4,
	rotateR: Math.PI / 12,
	rotateB: Math.PI / 12 * 2,
	rotateG: Math.PI / 12 * 3,
	scatter: 0,
	blending: 1,
	blendingMode: 1,
	greyscale: false,
	disable: false
};
const halftonePass = new HalftonePass( params );
composer.addPass( halftonePass );
```
```

--------------------------------

### Implement Unreal Bloom post-processing

Source: https://github.com/mrdoob/three.js/blob/dev/examples/webgl_postprocessing_unreal_bloom.html

Initializes the scene, loads a GLTF model, and configures the EffectComposer with UnrealBloomPass and GUI controls.

```javascript
import \* as THREE from 'three'; import Stats from 'three/addons/libs/stats.module.js'; import { GUI } from 'three/addons/libs/lil-gui.module.min.js'; import { OrbitControls } from 'three/addons/controls/OrbitControls.js'; import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js'; import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js'; import { RenderPass } from 'three/addons/postprocessing/RenderPass.js'; import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js'; import { OutputPass } from 'three/addons/postprocessing/OutputPass.js'; let camera, stats; let composer, renderer, mixer, timer; const params = { threshold: 0, strength: 1, radius: 0.5, exposure: 1 }; init(); async function init() { const container = document.getElementById( 'container' ); timer = new THREE.Timer(); timer.connect( document ); const scene = new THREE.Scene(); camera = new THREE.PerspectiveCamera( 40, window.innerWidth / window.innerHeight, 1, 100 ); camera.position.set( - 5, 2.5, - 3.5 ); scene.add( camera ); scene.add( new THREE.AmbientLight( 0xcccccc ) ); const pointLight = new THREE.PointLight( 0xffffff, 100 ); camera.add( pointLight ); const loader = new GLTFLoader(); const gltf = await loader.loadAsync( 'models/gltf/PrimaryIonDrive.glb' ); const model = gltf.scene; scene.add( model ); mixer = new THREE.AnimationMixer( model ); const clip = gltf.animations\[ 0 \]; mixer.clipAction( clip.optimize() ).play(); // renderer = new THREE.WebGLRenderer( { antialias: true } ); renderer.setPixelRatio( window.devicePixelRatio ); renderer.setSize( window.innerWidth, window.innerHeight ); renderer.setAnimationLoop( animate ); renderer.toneMapping = THREE.ACESFilmicToneMapping; container.appendChild( renderer.domElement ); // const renderScene = new RenderPass( scene, camera ); const bloomPass = new UnrealBloomPass( new THREE.Vector2( window.innerWidth, window.innerHeight ), 1.5, 0.4, 0.85 ); bloomPass.threshold = params.threshold; bloomPass.strength = params.strength; bloomPass.radius = params.radius; const outputPass = new OutputPass(); composer = new EffectComposer( renderer ); composer.addPass( renderScene ); composer.addPass( bloomPass ); composer.addPass( outputPass ); // stats = new Stats(); container.appendChild( stats.dom ); // const controls = new OrbitControls( camera, renderer.domElement ); controls.maxPolarAngle = Math.PI \* 0.5; controls.minDistance = 3; controls.maxDistance = 8; // const gui = new GUI(); const bloomFolder = gui.addFolder( 'bloom' ); bloomFolder.add( params, 'threshold', 0.0, 1.0 ).onChange( function ( value ) { bloomPass.threshold = Number( value ); } ); bloomFolder.add( params, 'strength', 0.0, 3.0 ).onChange( function ( value ) { bloomPass.strength = Number( value ); } ); gui.add( params, 'radius', 0.0, 1.0 ).step( 0.01 ).onChange( function ( value ) { bloomPass.radius = Number( value ); } ); const toneMappingFolder = gui.addFolder( 'tone mapping' ); toneMappingFolder.add( params, 'exposure', 0.1, 2 ).onChange( function ( value ) { renderer.toneMappingExposure = Math.pow( value, 4.0 ); } ); window.addEventListener( 'resize', onWindowResize ); } function onWindowResize() { const width = window.innerWidth; const height = window.innerHeight; camera.aspect = width / height; camera.updateProjectionMatrix(); renderer.setSize( width, height ); composer.setSize( width, height ); } function animate() { timer.update(); const delta = timer.getDelta(); mixer.update( delta ); stats.update(); composer.render(); }
```

--------------------------------

### Initialize and Add UnrealBloomPass to Composer

Source: https://github.com/mrdoob/three.js/blob/dev/docs/pages/UnrealBloomPass.html

This snippet demonstrates how to create an instance of UnrealBloomPass with a specified resolution, strength, radius, and threshold, then add it to a post-processing composer. When using this pass, tone mapping must be enabled in the renderer settings.

```javascript
const resolution = new THREE.Vector2( window.innerWidth, window.innerHeight );
const bloomPass = new UnrealBloomPass( resolution, 1.5, 0.4, 0.85 );
composer.addPass( bloomPass );
```

--------------------------------

### Initialize EffectComposer and Add Passes (JavaScript)

Source: https://github.com/mrdoob/three.js/blob/dev/docs/pages/EffectComposer.html.md

Initializes an EffectComposer with a renderer, adds a RenderPass, GlitchPass, and OutputPass, and demonstrates how to render the composer in the animation loop instead of the renderer.

```js
const composer = new EffectComposer( renderer );
// adding some passes
const renderPass = new RenderPass( scene, camera );
composer.addPass( renderPass );
const glitchPass = new GlitchPass();
composer.addPass( glitchPass );
const outputPass = new OutputPass()
composer.addPass( outputPass );
function animate() {
	composer.render(); // instead of renderer.render()
}
```

### Implement Custom Sky and Fog with ShaderMaterial

Source: https://github.com/mrdoob/three.js/blob/dev/manual/examples/background.html

Creates a custom ShaderMaterial using defined vertex and fragment shaders, applies uniforms, and adds a large sphere to simulate a sky with fog.

```javascript
if ( useFog ) { const vertexShader = ` varying vec3 vWorldPosition; void main() { vec4 worldPosition = modelMatrix * vec4( position, 1.0 ); vWorldPosition = worldPosition.xyz; gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 ); } `; const fragmentShader = ` uniform vec3 topColor; uniform vec3 bottomColor; uniform float offset; uniform float exponent; varying vec3 vWorldPosition; void main() { float h = normalize( vWorldPosition + offset ).y; gl_FragColor = vec4( mix( bottomColor, topColor, max( pow( max( h , 0.0), exponent ), 0.0 ) ), 1.0 ); } `; const uniforms = { topColor: { value: new THREE.Color( 0x88AABB ) }, bottomColor: { value: new THREE.Color( 0xEFCB7F ) }, offset: { value: 730 }, exponent: { value: 0.3 }, }; uniforms.topColor.value.copy( hemiLight.color ); scene.fog = new THREE.Fog( scene.background, fogNear, fogFar ); scene.fog.color.copy( uniforms.bottomColor.value ); const skyGeo = new THREE.SphereGeometry( 3000, 32, 15 ); const skyMat = new THREE.ShaderMaterial( { vertexShader: vertexShader, fragmentShader: fragmentShader, uniforms: uniforms, side: THREE.BackSide } ); const sky = new THREE.Mesh( skyGeo, skyMat ); scene.add( sky ); }
```

--------------------------------

### ShaderMaterial constructor — custom shader API

Source: https://github.com/mrdoob/three.js/blob/dev/src/materials/ShaderMaterial.js

ShaderMaterial is the API for custom GLSL shader effects. Users provide `uniforms`, `vertexShader`, and `fragmentShader` to define arbitrary per-fragment effects such as a holographic card. No built-in holographic effect exists; ShaderMaterial is the general-purpose base for one.

```javascript
class ShaderMaterial extends Material {

	constructor( parameters ) {

		super();

		this.isShaderMaterial = true;

		this.type = 'ShaderMaterial';

		this.defines = {};

		this.uniforms = {};

		this.uniformsGroups = [];

		this.vertexShader = default_vertex;

		this.fragmentShader = default_fragment;

		this.linewidth = 1;

		this.wireframe = false;

		this.wireframeLinewidth = 1;

		this.fog = false;

		this.lights = false;

		this.clipping = false;

		this.forceSinglePass = true;

		this.clipIntersection = false;

		this.clipShadows = false;

		this.castShadow = false;

		this.receiveShadow = false;

		this.flatShading = false;

		this.side = FrontSide;

		this.shadowSide = null;

		this.colorWrite = true;

		this.depthFunc = LessEqualDepth;

		this.depthTest = true;

		this.depthWrite = true;

		this.stencilWrite = false;

		this.stencilWriteMask = 0xff;

		this.stencilFunc = AlwaysStencilFunc;

		this.stencilRef = 0;

		this.stencilFuncMask = 0xff;

		this.stencilFail = KeepStencilOp;

		this.stencilZFail = KeepStencilOp;

		this.stencilZPass = KeepStencilOp;

		this.stencilCompare = AlwaysStencilFunc;

		this.glslVersion = null;

		this.linecap = 'round';

		this.linejoin = 'round';

		this.dashSize = 3;

		this.gapSize = 1;

		this.scale = 1;

		this.alphaToCoverage = false;

		this.forceMonoState = null;

		if ( parameters !== undefined ) {

			if ( parameters.attributes !== undefined ) {

				console.error( 'THREE.ShaderMaterial: attributes should now be defined in THREE.BufferGeometry' );

			}

			this.setValues( parameters );

		}

	}
```

--------------------------------

### How the renderer detects ShaderMaterial lighting needs

Source: https://github.com/mrdoob/three.js/blob/dev/src/renderers/WebGLRenderer.js

The WebGLRenderer's materialNeedsLights function shows that setting lights: true on a ShaderMaterial is the required flag for the renderer to pass lighting uniforms to the shader. This is the r171 WebGLRenderer API that gates the entire lighting pipeline for custom ShaderMaterials.

```javascript
function materialNeedsLights( material ) {

	return material.isMeshLambertMaterial || material.isMeshToonMaterial || material.isMeshPhongMaterial ||
		material.isMeshStandardMaterial || material.isShadowMaterial ||
		( material.isShaderMaterial && material.lights === true );

}
```

--------------------------------

### Transparent ShaderMaterial with UniformsUtils.merge and UniformsLib.fog

Source: https://github.com/mrdoob/three.js/blob/dev/examples/jsm/objects/Water2.js

Shows the transparent: true flag combined with UniformsUtils.merge([UniformsLib['fog'], shader.uniforms]) on a ShaderMaterial. This is the pattern for alpha-blended custom materials that also need fog.

```javascript
this.material = new ShaderMaterial( {
	name: shader.name,
	uniforms: UniformsUtils.merge( [
		UniformsLib[ 'fog' ],
		shader.uniforms
	] ),
	vertexShader: shader.vertexShader,
	fragmentShader: shader.fragmentShader,
	transparent: true,
	fog: true
} );
```

--------------------------------

### MeshStandardMaterial fragment shader chunk ordering

Source: https://github.com/mrdoob/three.js/blob/dev/src/renderers/shaders/ShaderLib/meshphysical.glsl.js

The complete fragment shader for MeshStandardMaterial (shaderID 'physical'), showing the exact #include order of all shader chunks in both the declaration section and main() body. Essential for custom onBeforeCompile to know where to insert or replace chunks.

```javascript
export const fragment = /* glsl */`
#define STANDARD

#ifdef PHYSICAL
	#define IOR
